/* 일망호 대기방 표식 — images/normal/20261104202815~26의 원본 해상도 PNG 조각.
   다른 이미지 라이브러리로 미리 계산한 해시를 쓰지 않는다. 기준 이미지와 공유 프레임
   모두 주변 배경 대비로 이진화한 글자 마스크로 비교한다.
   데이터는 두 고정 표식뿐이며 닉네임·방 이름은 포함하지 않는다. */
(function (global) {
    'use strict';
    const marks = [{"rect":[170,31,126,32],"sources":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"]},{"rect":[920,48,96,28],"sources":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"]}];
    const textBoxes = [[0, 0, 126, 32], [0, 0, 96, 28]]; // ONLINE, FREE만 남긴다.
    let loaded = false, error = null;
    const loadImage = src => new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error('일망호 대기방 기준 이미지 로딩 실패'));
        img.src = src;
    });

    // 밝은 글자만 추출한다. 고정 밝기 대신 주변 9×9 평균과 영상의 밝기 범위를 쓴다.
    function textMask(source, rect, width, height) {
        const canvas = document.createElement('canvas');
        canvas.width = width; canvas.height = height;
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        ctx.drawImage(source, ...rect, 0, 0, width, height);
        const pixels = ctx.getImageData(0, 0, width, height).data;
        const gray = new Float32Array(width * height), sorted = [];
        const stride = width + 1, sum = new Float64Array(stride * (height + 1));
        for (let y = 0; y < height; y++) {
            let row = 0;
            for (let x = 0; x < width; x++) {
                const i = y * width + x, p = i * 4;
                const v = (pixels[p] + pixels[p + 1] + pixels[p + 2]) / 3;
                gray[i] = v; sorted.push(v); row += v;
                sum[(y + 1) * stride + x + 1] = sum[y * stride + x + 1] + row;
            }
        }
        sorted.sort((a, b) => a - b);
        const low = sorted[Math.floor(sorted.length * 0.2)], high = sorted[Math.floor(sorted.length * 0.9)];
        const threshold = (low + high) / 2;
        const bits = new Uint8Array(gray.length);
        let ink = 0;
        if (high - low >= 12) {
            for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
                const x0 = Math.max(0, x - 4), x1 = Math.min(width, x + 5);
                const y0 = Math.max(0, y - 4), y1 = Math.min(height, y + 5);
                const mean = (sum[y1 * stride + x1] - sum[y0 * stride + x1]
                    - sum[y1 * stride + x0] + sum[y0 * stride + x0]) / ((x1 - x0) * (y1 - y0));
                const i = y * width + x;
                if (gray[i] > threshold && gray[i] - mean >= 7) { bits[i] = 1; ink++; }
            }
        }
        return { bits, width, height, ink };
    }

    // ±2px 위치 오차와 축소·압축에 따른 1px 획 두께 차이를 허용하며 양방향 누락을 잰다.
    function maskDistance(a, b) {
        if (a.ink < 30 || b.ink < 30 || Math.min(a.ink, b.ink) / Math.max(a.ink, b.ink) < 0.45) return 1;
        const covered = (mask, x, y) => {
            for (let yy = y - 1; yy <= y + 1; yy++) for (let xx = x - 1; xx <= x + 1; xx++) {
                if (xx >= 0 && yy >= 0 && xx < mask.width && yy < mask.height && mask.bits[yy * mask.width + xx]) return true;
            }
            return false;
        };
        let best = 1;
        for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) {
            let missing = 0, extra = 0;
            for (let y = 0; y < a.height; y++) for (let x = 0; x < a.width; x++) {
                const i = y * a.width + x;
                if (a.bits[i] && !covered(b, x + dx, y + dy)) missing++;
                if (b.bits[i] && !covered(a, x - dx, y - dy)) extra++;
            }
            best = Math.min(best, Math.max(missing / a.ink, extra / b.ink));
        }
        return best;
    }

    const ready = Promise.all(marks.map(async (mark, k) => {
        const images = await Promise.all(mark.sources.map(loadImage));
        mark.text = textBoxes[k];
        mark.masks = images.map(img => textMask(img, mark.text, mark.text[2], mark.text[3]));
        delete mark.sources;
    })).then(() => { loaded = true; }, e => { error = e.message; console.error('[GeneralLobby]', e); });

    function read(frame, W, H) {
        if (!loaded || !frame || !W || !H) return { ready: loaded, match: false, error };
        const results = marks.map(mark => {
            const [mx, my] = mark.rect, [x, y, w, h] = mark.text;
            const mask = textMask(frame, [(mx + x) * W / 2560, (my + y) * H / 1440, w * W / 2560, h * H / 1440], w, h);
            const distance = Math.min(...mark.masks.map(ref => maskDistance(mask, ref)));
            return { distance, limit: 0.2, ink: mask.ink, match: distance <= 0.2 };
        });
        return { ready: true, match: results.every(result => result.match), markers: results };
    }
    global.VMH.GeneralLobby = { read, ready };
})(window);
